def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def level_sums(tree):
    root = _build(tree)
    if root is None:
        return []
    result = []
    level = [root]
    while level:
        result.append(sum(n['val'] for n in level))
        nxt = []
        for n in level:
            if n['left']:
                nxt.append(n['left'])
            if n['right']:
                nxt.append(n['right'])
        level = nxt
    return result
